Review this React 19.3 component and rewrite it the way the React docs recommend. It reconnects to the chat every time the theme changes, and the filtered list sometimes flashes stale data.

```jsx
function ChatRoom({ roomId, theme, messages, query }) {
  const [visible, setVisible] = useState([]);
  useEffect(() => {
    setVisible(messages.filter(m => m.text.includes(query)));
  }, [messages, query]);

  const ignore = useRef(false);
  useEffect(() => {
    if (ignore.current) return;
    ignore.current = true;
    const connection = createConnection(serverUrl, roomId);
    connection.on('connected', () => {
      showNotification('Connected!', theme);
    });
    connection.connect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [roomId, theme]);

  return <List items={visible} />;
}
```

